package com.huan.capture.sr.webrtc.capture;import android.content.Context;import android.content.Intent;import android.os.Build;import com.huan.capture.sr.ScreenVideoSourceService;import org.webrtc.VideoCapturer;/** * <br> * * <br> */public class ScreenVideoCaptureAdapter extends VideoCaptureAdapter {    public void startScreenCapture(Context context, Intent data, Runnable callback) {        ScreenVideoSourceService.setCallback(new ScreenVideoSourceService.Callback() {            @Override            public Intent getMediaProjectionPermissionResultData() {                return data;            }            @Override            public void onCreateVideoCapture(VideoCapturer videoCapturer) {                mVideoCapture = videoCapturer;                callback.run();            }        });        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {            context.startForegroundService(new Intent(context, ScreenVideoSourceService.class));        }    }}